    // 1. Adaptive Dead-Space Penalty:
    // Avoid creating small, unusable gaps. 1-15 is highly toxic.
    if post_residual > 0 && post_residual < 16 {
        score += 55.0 + (16.0 - post_residual as f64) * 2.5;
    }

    // 2. Lookahead Synergy:
    // If the next item fits, reduce score significantly.
    // Bonus is higher if we leave a 'comfortable' residual space (>= 20) for future items.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0;
        if (post_residual - next_item_size) >= 20 {
            score -= 25.0;
        }
    }

    // 3. Scarcity Constraint:
    // If this is the only bin that can accommodate the item, it becomes the mandatory choice.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // 4. Mean-Alignment Regularization:
    // Keep bin usage consistent with the global mean to minimize variance.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.22;

    // 5. Dynamic New-Bin Thresholding:
    // Opening a new bin is expensive. 
    // Penalty increases slightly as we progress to favor compaction in early bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score += 35.0 + (progress * 25.0);
    } else {
        // 6. Prefer deeper packing:
        // Reward existing bins that keep residuals low.
        score += post_residual as f64 * 0.4;
    }

