        score -= 40.0;
    }

    // 8. Open Bin Count Penalty:
    // Discourage keeping too many bins open simultaneously if we have high capacity remaining.
    if open_bins_count > 5 && bin_residual > (bin_capacity / 2) {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Start with the residual as the base cost (Best Fit logic)
    let mut score = post_residual as f64;

    // 1. Adaptive Dead-Space Penalty:
    // Small residuals are toxic. We define 'small' as < 25 (covering most common items).
    if post_residual > 0 && post_residual < 25 {
        score += 45.0 + (25.0 - post_residual as f64) * 2.0;
