            score -= 15.0;
        }
    }

    // 3. Scarcity Constraint:
    // If this is the only bin that can accommodate the item, it becomes the mandatory choice.
    if fitting_bins_count == 1 {
        score -= 100.0;
    }

    // 4. Mean-Alignment Regularization:
    // Keep bin usage consistent with global trends to prevent outliers.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.15;

    // 5. Dynamic New-Bin Thresholding:
    // Opening a new bin is expensive, but the penalty should scale to prevent
    // "bin-starvation" late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        // As we reach the end, opening a new bin is relatively cheaper than forcing a bad fit.
        score += 45.0 - (progress * 15.0);
    } else {
        // 6. Prefer Best Fit:
        // Reward bins that have already been used, favoring deeper packing.
        score += post_residual as f64 * 0.3;
    }

    // 7. Capacity Efficiency: 
    // If the post_residual is nearly zero (perfect fit), provide a significant bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

