        score -= 240.0;
    }

    // 7. Global Consolidation: Penalize sprawl more heavily
    if open_bins_count > 4 {
        score += (open_bins_count as f64 - 4.0).powf(1.1) * 22.0 * (1.1 - progress);
    }

