    if item_size > 62 {
        score -= (bin_capacity - bin_residual) as f64 * 0.82;
    } else if item_size < 24 {
        score += (bin_capacity - bin_residual) as f64 * 0.48;
    }

    // 9. Fragmentation Mitigation: Prohibit small-item "bin-pollution"
