pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalty for creating "dead space" (small residuals that are hard to fill)
    // We penalize residuals in the range [1, 9] heavily as they are unlikely to fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead optimization: If the next item could fit in the current post_residual,
    // we reward this placement to keep the bin useful for the immediate future.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Global state management: Balance the load.
    // If we have many open bins, we want to prioritize filling the most crowded ones (Best Fit).
    // If we have few open bins, we prioritize keeping the residual space high for flexibility.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score += (open_bins_count as f64) * fill_ratio * 2.0;

    // 4. Dynamic threshold for opening new bins:
    // When residual == capacity, we are evaluating a NEW bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean residual is already quite low,
        // or if we are nearing the end of the stream and need to clear out remaining items.
        let penalty = 15.0 + (mean_residual * 0.5) + (progress * 20.0);
        score += penalty;
    } else {
        // If it's an existing bin, reward it if it's the only option left.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

