    }

    // 3. Lookahead coupling: If next_item_size is large, favor keeping larger residuals
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Cannot fit next item, penalize this bin slightly if other bins exist
            score += 15.0 * (open_bins_count as f64 / (fitting_bins_count as f64 + 1.0));
        } else {
            // Can fit next item, reward this bin
            score -= 10.0;
        }
    }

    // 4. Distribution balancing: Encourage filling bins that are already "below average"
    // relative to the mean residual of open bins.
    if (bin_residual as f64) < mean_residual {
