pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize Best Fit (minimize post_residual)
    let mut score = post;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We penalize values that are small but non-zero, especially as we approach the end of the stream.
    if post > 0.0 && post < 15.0 {
        score += (15.0 - post) * (1.0 + progress * 2.0);
    }

    // Lookahead logic: if next_item_size is known, penalize residuals that can't fit it.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 1.5;
        }
    }

    // Balance open bins: avoid opening new bins unless necessary.
    // If bin_residual == bin_capacity, this is a new bin candidate.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if an existing one can accommodate the item.
            // This penalty scales with stream progress to be more conservative late-game.
            score += 40.0 + (progress * 30.0) + (open_bins_count as f64 * 2.0);
        } else {
            // No other choice, normalize to be competitive.
            score = 25.0; 
        }
    } else {
        // Reward bins that keep the mean_residual high (more flexibility for future large items).
        // Coupling the residual with the global mean to favor densification.
        score -= (post - mean_residual).powi(2) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
