        score -= 165.0 / (fitting_bins_count as f64).sqrt();
    }

    // 4. Mean-Alignment Regularization
    // Penalize deviation from the mean residual to maintain uniform bin fill levels.
    score += (post_residual as f64 - mean_residual).abs() * 0.72;

    // 5. Dynamic New-Bin Thresholding
    if bin_residual == bin_capacity {
        // High cost to open a new bin, scaling with progress to allow for more bins at the end.
        score += 105.0 + (progress * 130.0);
    } else {
        // Encourage using existing bins by penalizing the "wasted potential" of partially filled bins.
        score += (bin_capacity - bin_residual) as f64 * 0.15;
    }

    // 6. Perfect Fit Bonus
    if post_residual == 0 {
        score -= 160.0;
    }

    // 7. Global Open Bin Management
    // Stronger penalty for excessive bins in the mid-to-late game to force consolidation.
    if open_bins_count > 6 {
        score += (open_bins_count as f64 - 6.0) * 15.0 * (1.0 - (progress * 0.3));
    }

    // 8. Large Item Bias
    // If the item is large, favor bins that have space, as they become harder to fill later.
    if item_size > 60 {
        score -= (bin_capacity - bin_residual) as f64 * 0.55;
    }

