    }

    // 4. Mean-Alignment Regularization:
    // Penalize deviation from the current mean to maintain uniform bin usage.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.45;

    // 5. Dynamic New-Bin Thresholding:
    // Increase new bin cost linearly to force consolidation, but allow more flexibility if open_bins_count is low.
    if bin_residual == bin_capacity {
        score += 75.0 + (progress * 100.0) - (open_bins_count as f64 * 2.0);
    } else {
        // Penalty for under-utilizing existing capacity
        score += (bin_capacity - bin_residual) as f64 * 0.22;
    }

    // 6. Perfect Fit Bonus:
    // Strong incentive for exact fills.
    if post_residual == 0 {
        score -= 110.0;
    }

    // 7. Global Open Bin Management:
    // Penalize high open bin counts; this prevents "scatter-packing" early in the stream.
    if open_bins_count > 8 {
        score += (open_bins_count as f64 - 8.0) * 4.0 * (1.0 - progress);
    }

