}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    // We want to minimize post_residual (Best Fit), but with non-linear adjustments.
    let mut score = post_res;

    // Penalty for leaving small, unusable gaps (1..10) that are difficult to fill later.
    // This penalty is scaled by progress; as we reach the end of the stream, 
    // we care less about small gaps and more about fitting the final items.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * (1.0 - 0.5 * progress);
    }

    // Lookahead logic: if the next item is large, favor bins that can accommodate it.
    // If the current post_residual is smaller than the next item, penalize this bin.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size as f64 - post_residual as f64) * 0.8;
    }

    // New Bin Logic: Discourage opening a new bin unless the fit is extremely poor.
    // As progress increases, the cost of opening a new bin should effectively decrease 
    // to ensure no items are left behind due to overly restrictive packing.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin is 35.0, adjusted by progress.
        score = 35.0 - (progress * 15.0);
    } else {
        // If the bin is not new, reward bins that are closer to the mean residual 
        // to keep bin utilization balanced (prevents "bin fragmentation").
        let deviation = (post_res - mean_residual).abs();
        score += deviation * 0.2 * progress;
    }

