    // 1. Best-Fit logic: Penalize large post_residuals (dead space)
    // 2. Harmonic Class logic: If post_residual is small, it's often better to 
    //    keep bins "tight" to allow future items to fit.

    // Penalize creating small, unusable gaps (1-9) that are difficult to fill
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; 
    }

    // Lookahead logic: If the next item fits into the current post_residual, 
    // reward this bin heavily to increase packing density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // Capacity fraction logic: Favor bins that are already well-utilized
    let utilization = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= utilization * 10.0;

    // Threshold logic: If this is the only bin that fits the item (fitting_bins_count == 1),
    // we should prioritize using it to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // New bin penalty: If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // Only open if the current packing state is very poor.
    if bin_residual == bin_capacity {
        // High base score to discourage opening new bins unless necessary
        score = 60.0;
        // If we are late in the stream, be even more conservative about new bins
        score += (step_index as f64 / total_items as f64) * 20.0;
    }

    // Modulo-based penalty: Avoid "fragmentation" by penalizing post_residuals 
    // that are prime or near common item sizes.
    if post_residual % 11 == 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    // Base score: Focus on post-fit density.
    let mut score = post_residual as f64 * (2.8 + progress * 3.2);

    // 1. Predictive Lookahead: Adjusting for the next item to minimize stranded space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect fit is the primary objective for compaction.
            let synergy = if post_residual == next_item_size { 310.0 } else { 145.0 };
            score -= synergy * (1.1 - progress * 0.15);
        } else if post_residual > 0 {
            // Severe penalty for creating a "dead zone" that cannot host the next item.
            score += (240.0 - (post_residual as f64 * 2.0)) * (1.0 - progress * 0.05);
        }
    }

    // 2. Bin Lifecycle & Fragmentation:
    if is_new_bin {
        // Threshold refinement: discourage new bins unless existing options are critically poor.
        let fragmentation_cost = (open_bins_count as f64).powf(1.42) * 92.0;
        score += 260.0 + (progress * 180.0) + fragmentation_cost;
    } else {
        // 3. Variance & Stability:
        // Use fill_ratio to normalize the target residual, pushing toward a more uniform distribution.
        let target_residual = mean_residual * (1.0 - (progress * 0.2));
        let deviation = (bin_residual as f64 - target_residual).abs();
        score += (deviation / bin_capacity as f64).powi(2) * 280.0;

        // 4. Sliver Avoidance:
        if post_residual < 6 {
            score -= (250.0 - (post_residual as f64 * 30.0));
        }
    }

    // 5. Fitting Pressure:
    if fitting_bins_count > 0 {
        // Increased sensitivity to fitting options to conserve open bins.
        score -= 420.0 / (fitting_bins_count as f64 + 0.5).powf(2.4);
    }

    // 6. Dynamic Phase-Specific Compaction:
    if progress > 0.92 {
        // End-game: Prioritize clearing out the smallest residuals regardless of mean.
        score -= (bin_capacity - post_residual) as f64 * 2.1;
    } else if progress < 0.12 {
        // Early-game: Establish high-density bins to set a low mean_residual.
        score -= fill_ratio * 450.0;
    }

    // 7. Entropy/Closure:
    // Reward bins that reach a near-full state (residual < 5% of capacity).
    if post_residual < (bin_capacity / 20) && !is_new_bin {
        score -= 180.0 * (1.0 - progress * 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

