        // For existing bins, reward tighter fits to consolidate space
        score += (1.0 - (post_residual as f64 / bin_capacity as f64)) * 10.0;
    }

    // 4. Global state awareness: If we are late in the stream, prioritize closing bins
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && post_residual < 20 {
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / (total_items as f64).max(1.0)).clamp(0.0, 1.0);
    let is_new_bin = bin_residual == bin_capacity;

