    // Scale penalty with progress to tighten constraints as the bin stream depletes.
    let mut score = post_residual as f64 * (2.45 + progress * 2.85);

    // 1. Adaptive Lookahead: Prioritize bins that perfectly accommodate the next item.
    // Use a non-linear decay for the benefit of future-proofing to avoid over-constrained early bins.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let synergy = if post_residual == next_item_size { 310.0 } else { 145.0 };
            score -= synergy * (1.15 - progress * 0.35);
        } else if post_residual > 0 && post_residual < (next_item_size / 2) {
            // Penalize creating "dead zones" that are too small for the next item.
            score += 240.0 * (1.0 - progress * 0.2);
        }
    }

    // 2. Bin Lifecycle Management: Penalize new bin creation to force high utilization.
    // The penalty grows exponentially with the count of already open bins to combat fragmentation.
    if is_new_bin {
        let base_new_penalty = 255.0;
        let fragmentation_cost = (open_bins_count as f64).powf(1.42) * 92.0;
        score += base_new_penalty + (progress * 185.0) + fragmentation_cost;
    } else {
        // 3. Global Load Balancing: Minimize variance from the mean to ensure uniform packing.
        let residual_diff = (bin_residual as f64 - mean_residual).abs();
        score += (residual_diff / bin_capacity as f64).powi(2) * 265.0;

        // 4. Sliver Avoidance: Reward near-perfect utilization (0-7 residual).
        if post_residual < 8 {
            score -= (245.0 - (post_residual as f64 * 30.0));
        }
    }

    // 5. Fitting Pressure: If many bins can fit the item, prefer those that increase mean_residual
    // density, but penalize scarcity to avoid closing bins prematurely.
    if fitting_bins_count > 0 {
        score -= 380.0 / (fitting_bins_count as f64).powf(2.4);
    }

    // 6. Phase-Specific Compaction:
    if progress > 0.94 {
        // Late-stage: Aggressive residual minimization to flush remaining capacity.
        score += post_residual as f64 * 210.0;
    } else if progress < 0.06 {
        // Early-stage: Favor high-density clusters to establish a stable bin mean.
        score += (bin_capacity - bin_residual) as f64 * 2.8;
    }

    // 7. Entropy Reduction: Bonus for perfectly filled bins.
    if post_residual == 0 && !is_new_bin {
        score -= 160.0;
    }

    score
}

