    // Keep bins close to the global mean to maximize future fitting potential.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.25;

    // 4. Scarcity Constraint
    // If this is the only bin that fits the item, we must take it.
    // We heavily incentivize this to prevent opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 75.0;
    }

    // 5. New Bin Cost Function
    // We model the "cost" of a new bin as a function of stream progression and current capacity.
    // As we reach the end of the stream, opening new bins becomes exponentially worse.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        // Base penalty 40, increasing to 60 as we approach the end of the stream.
        score += 40.0 + (progress * 20.0);
    }

    // 6. Entropy Mitigation
    // If we have many open bins, penalize bins that are "too empty" to force consolidation.
    if open_bins_count > 5 {
        score += (bin_capacity - bin_residual) as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Start with the primary goal: minimize post_residual (Best Fit)
    // We transform this into a weight that penalizes large gaps.
    let mut score = post_residual as f64 * 1.5;

    // 1. Adaptive Lookahead: Prioritize bins that accommodate the next item.
    // We weight this heavily to prevent fragmentation.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 45.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Penalize "near-miss" bins that will force a new bin for the next item
            score += 15.0;
