    // 2. Dead-space avoidance: If the remaining space is too small for common items (e.g., < 15),
    // we penalize it unless it's a perfect fit (0).
    if post_residual > 0 && post_residual < 15 {
        score += 25.0;
    }

    // 3. Dynamic New-Bin Thresholding:
    // Opening a new bin is expensive. We scale this cost by the current bin population
    // to discourage excessive bin creation in the late stages of the stream.
    if bin_residual == bin_capacity {
        let completion_ratio = step_index as f64 / total_items as f64;
        let base_cost = 45.0 + (completion_ratio * 40.0);
        let population_penalty = (open_bins_count as f64).sqrt() * 5.0;
        score += base_cost + population_penalty;
    } else {
        // 4. Compactness Bias: If fitting into an existing bin, reward 
        // bins that are already well-utilized (lower mean_residual).
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // 5. Critical Constraint: If this is the only bin that can house the item,
    // negate the score to ensure it is selected regardless of "dead space" penalties.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 6. Variance Smoothing: Penalize extreme deviations from the mean
    // to encourage a uniform packing density across all active bins.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Start with a base cost derived from the post_residual, favoring tighter fits (Best Fit)
    let mut score = post_residual as f64 * 0.85;

