    let mut score = post;

    // Penalty for creating small, unusable gaps (under 10 units)
    // We penalize harder as the stream progresses to consolidate space.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * (2.0 + 3.0 * progress);
    }

    // Heuristic for new bin creation:
    // If the bin is new, calculate the cost of opening it.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean residual is already quite low,
