        score -= 55.0;
        // Further reward if this fit leaves a near-zero residual for the next item
        if (post_residual - next_item_size) < 5 {
            score -= 15.0;
        }
    }

    // 3. Adaptive New-Bin Cost:
    // Opening a new bin is expensive, but the cost must scale with the stream progress.
    // Early on, we are more flexible; late in the stream, we force tighter packing.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score += 45.0 + (progress * 30.0);
    } else {
        // 4. Entropy Control:
        // Penalize bins that deviate from the mean residual to prevent "outlier bins" 
        // that are significantly emptier than the average.
        let dev_from_mean = (post_residual as f64 - mean_residual).abs();
        score += dev_from_mean * 0.15;
    }

    // 5. Scarcity Logic:
    // If this is the only bin that can fit the item, it is a "must-take" bin.
    // We heavily discount its score to ensure it is selected over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // 6. Tightness Bias:
    // Fine-tune the preference for smaller residuals to favor Best Fit over First Fit.
    score += (post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for opening a new bin:
    // If bin_residual == bin_capacity, this is the "new bin" candidate.
    // We penalize it significantly to favor filling existing bins, 
    // unless the open bins are already very full (mean_residual is low).
    if bin_residual == bin_capacity {
        score += 85.0 - (mean_residual * 0.5);
    }

    // 2. Lookahead optimization (Best-Fit-Decreasing style logic):
    // If we have a next_item, we want to prioritize bins where the post_residual
    // is closest to the next_item_size without going negative.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that perfectly accommodate the next item (synergy)
            score -= (100.0 - (post_residual as f64 - next_item_size as f64).abs()) * 0.2;
        } else {
            // Penalize bins that are now too small for the next item
            score += 15.0;
        }
    }

    // 3. Efficiency pressure:
    // If this is the ONLY bin that can fit the item, we should take it 
    // to avoid fragmentation, unless the resulting residual is extremely small (fragmentation trap).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual < 10 {
            score += 20.0; // Avoid creating "unusable" slivers
        } else {
            score -= 10.0; // Take the fit
        }
    }

    // 4. Global progress weighting:
    // As we approach the end of the stream, prioritize tighter packing
    // to minimize the number of bins left open.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base score is the residual after placement (Best Fit logic)
    let mut score = post_residual as f64;

    // 1. Dynamic Lookahead: Reward bins that perfectly accommodate the next item (zero waste)
    // or leave enough room to avoid fragmentation.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            score -= 15.0;
        }
    }

    // 2. Anti-Fragmentation: Penalize "sliver" residuals that are too small to be useful
    // for standard items (items < 20).
    if post_residual > 0 && post_residual < 18 {
        score += 32.0 - (post_residual as f64 * 0.5);
    }

    // 3. Density Pressure: As the stream progresses, prioritize closing gaps.
    // If the bin is already quite full, reward keeping it that way.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    // 4. New Bin Threshold: Heavier penalty for new bins to force consolidation.
    // Scale penalty by the number of open bins to prevent excessive bin growth.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        let openness_penalty = (open_bins_count as f64).sqrt() * 15.0;
        score += 55.0 + (progress * 25.0) + openness_penalty;
    }

    // 5. Variance Smoothing: Dampen the tendency to pick extreme residuals.
    // Penalize deviation from the historical mean to encourage uniform packing.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.25;

    // 6. Scarcity Logic: If few bins can fit the item, prioritize the most efficient one
    // to avoid forcing a new bin later.
    if fitting_bins_count < 3 {
        score -= 10.0;
    }

    // 7. Efficiency Bias: Small weight to keep post_residual low (Best Fit)
    score += (post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Best Fit Decreasing logic combined with lookahead-based fragmentation avoidance.
    // The objective is to minimize post_residual (Best Fit) while penalizing 
    // configurations that leave "orphaned" gaps that cannot accommodate future items.

    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalize opening a new bin if other options exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // High penalty for opening a new bin proportional to potential waste.
        score += 85.0 * (1.0 + progress);
    }

    // 2. Lookahead: If the next item is large, avoid creating a post_residual 
    // that is just slightly smaller than the next item (creating unusable gaps).
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            // This is a "fragmentation" trap.
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
        // Reward placements that leave exactly enough room for the next item.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // 3. Global State: Penalize deviating from the mean residual to keep bin fill levels uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 4. Criticality: If this is the last bin that can fit the item, prioritize it 
    // to avoid opening a brand-new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 5. Prefer tighter packing as the stream approaches the end.
    if progress > 0.8 {
        score += post_residual as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Start with the base residual: tighter fits (lower post_residual) are inherently better.
    let mut score = post_residual as f64 * 0.85;

    // 1. Lookahead heuristic: If the next item fits in the remaining space, we heavily reward this bin.
    // This acts as a primary compaction driver to prevent fragmentation.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64 * 1.2) + 15.0;
    }

    // 2. Dead-space avoidance: If the residual is too small for meaningful future items, 
    // it's "trapped" space. We penalize small non-zero remainders.
    if post_residual > 0 && post_residual < 12 {
        score += 25.0 / (post_residual as f64 + 0.1);
    }

    // 3. Adaptive open-bin management:
    if bin_residual == bin_capacity {
        // Opening a new bin is a last resort. 
        // We scale the cost based on the number of open bins to prevent "bin proliferation."
        let progress = step_index as f64 / total_items as f64;
        score += 45.0 + (open_bins_count as f64 * 2.5) + (progress * 15.0);
    } else {
        // 4. Global equilibrium: Prefer bins that move the current state towards the global mean.
        // This keeps packing density consistent across all active bins.
        let dev_from_mean = (post_residual as f64 - mean_residual).abs();
        score += dev_from_mean * 0.25;
    }

    // 5. Urgency factor: If few bins can fit the item, we must prioritize using an existing one
    // to avoid the high cost of opening a new bin.
    if fitting_bins_count > 0 && fitting_bins_count < 3 {
        score -= 10.0 * (3.0 - fitting_bins_count as f64);
    }

    // 6. Large-item preservation: If the item is large, favor bins where it fits perfectly 
    // to preserve smaller residual holes for smaller future items.
    if item_size > 60 && post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: non-linear growth as the stream progresses.
    // Early on, we are more willing to open new bins to maintain flexibility.
    // Near the end, we penalize new bin creation heavily to force consolidation.
    if is_new_bin {
        score += 15.0 + (progress * 45.0).powf(1.5);
    } else {
        // Reward bins that leave residual space close to the next_item_size
        // This creates a "lookahead" pressure to keep bins compatible for future items.
        if next_item_size > 0 {
            let diff = (post_residual as f64 - next_item_size as f64).abs();
            score -= 10.0 * (1.0 / (1.0 + diff));
        }

        // Penalize bins that create "dead space" (small, unusable residuals)
        // A residual < 10 is often useless since min item size is 10.
        if post_residual > 0 && post_residual < 10 {
            score += 20.0 * (1.0 - (post_residual as f64 / 10.0));
        }
    }

    // Encourage using existing bins if they are already "half-full" to keep mean_residual balanced
    // This acts as a stabilizer against fragmented bin states.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score += (fill_ratio - 0.5).powi(2) * 5.0;

    // If this is the last fitting bin, slightly reward placing here to prevent 
    // unnecessary bin proliferation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base score: prioritize tighter fits (Best Fit)
    let mut score = post_residual as f64 * 0.45;

    // 1. Lookahead optimization: Heavily prioritize bins that accommodate the next item
    // to preserve capacity for future constraints.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 42.0;
        } else if bin_residual >= next_item_size {
            // If we don't fit the next item, penalize the bin proportionally to the mismatch
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // 2. Fragment avoidance: Penalize "sliver" residuals that are unlikely to fit 
    // standard items (threshold 1-15).
    if post_residual > 0 && post_residual <= 15 {
        score += 28.0;
    }

    // 3. Adaptive New Bin logic: 
    // Opening a new bin is expensive, but becomes increasingly attractive if 
    // existing bins are highly fragmented (high open_bins_count).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        let fragmentation_pressure = (open_bins_count as f64 / (step_index as f64 + 1.0)) * 50.0;
        score += 55.0 + (progress * 15.0) - fragmentation_pressure;
    }

    // 4. Global balance: Encourage packing towards the mean to avoid extreme tail bins
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.15;

    // 5. Scarcity handling: If only one bin can fit this item, prioritize it 
    // to avoid "locking" a bin that could have taken a larger item later.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 6. Efficiency dampener: Favor bins that are already partially filled 
    // to minimize the count of active bins.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Adaptive Dead-Space Penalty:
    // Instead of a static threshold, scale the penalty based on the ratio of next_item_size.
    // Small gaps are worse if the next item is likely to be large.
    if post_residual > 0 && post_residual < 15 {
        score += 45.0 + (next_item_size as f64 * 0.4);
    }

    // 2. Multi-stage Lookahead:
    // Reward bins that leave space for the next item, but penalize if the resulting
    // post_residual becomes a "fragile" size (too small for most items).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 42.0;
        } else if post_residual > 0 {
            score += 15.0; // Penalty for blocking the next item
        }
    }

    // 3. Density-weighted Fit:
    // Favor bins that have a high filling ratio to reduce open_bins_count.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // 4. Entropy Control:
    // If we have many open bins, aggressively prioritize closing gaps (Best Fit).
    // If we have few open bins, prioritize keeping space for future items.
    let open_penalty = (open_bins_count as f64).min(20.0) * 1.5;
    score += (post_residual as f64 * 0.3) * (1.0 + (open_penalty / 50.0));

    // 5. New Bin Heuristic:
    // Calculate the "opportunity cost" of opening a new bin vs reusing.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        // Exponentially discourage new bins as we approach the end of the stream.
        score += 45.0 + (progress * 40.0) + (open_bins_count as f64 * 0.8);
    } else {
        // 6. Near-perfect fit reward:
        // If the bin is almost full, prioritize it to minimize fragmentation.
        if post_residual < 5 {
            score -= 10.0;
        }
    }

    // 7. Global mean stabilization:
    // Penalize deviation from the mean, but reduce sensitivity as the stream grows.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: Minimize post_residual
    // 2. Penalty for creating "slivers" (dead space < 10):
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead Harmony: If next_item_size is large, favor larger post_residual
    // to accommodate it (Best Fit vs Worst Fit hybrid)
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // High penalty if we block the next item from fitting
            score += 60.0;
        } else {
            // Reward if we leave space that perfectly matches the next item
            let delta = (post_residual as f64 - next_item_size as f64).abs();
            score -= 20.0 / (1.0 + delta);
        }
    }

    // 4. New Bin Thresholding:
    // If this is a new bin (residual == capacity), penalize it based on how many
    // bins are already open and how much space is left in current ones.
    if bin_residual == bin_capacity {
        // Only open new if we are forced or if existing bins are very cluttered
        score += 40.0; 
        score += (open_bins_count as f64) * 0.5;
        score -= (100.0 - mean_residual) * 0.2;
    }

    // 5. Harmonic Class encouragement:
    // Favor bins that result in post_residual being a multiple of 20 (common item sizes)
    if post_residual % 20 == 0 {
        score -= 15.0;
    }

    // 6. Progression scaling:
    // Toward the end of the stream, be more conservative with opening new bins
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Start with the residual as base: smaller residual = tighter fit.
    let mut score = post_residual as f64;

    // 1. Adaptive Dead-Space Penalty:
    // Avoid creating small, unusable gaps. If the bin is now "near-empty" (small post_residual),
    // penalize heavily unless the residual is exactly zero (perfect fit).
    if post_residual > 0 && post_residual < 18 {
        score += 48.0 - (post_residual as f64 * 0.8);
    }

    // 2. Multi-Stage Lookahead:
    // Prioritize bins that accommodate the next item comfortably, but apply a non-linear 
    // reward scaling to favor "tight" lookahead fits over "loose" ones.
    if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = (post_residual - next_item_size) as f64;
        score -= 45.0 - (tightness * 0.2);
    }

    // 3. Forced Selection Adjustment:
    // If we have limited options, prioritize consolidation.
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 4. Entropy Control:
    // Penalize bins that drift away from the current mean residual to maintain uniform bin states.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.35;

    // 5. Dynamic New-Bin Cost:
    // Exponentially increase the cost of opening a new bin as the stream progresses.
    // This forces the algorithm to be more aggressive with packing in the final stages.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score += 55.0 + (progress * 45.0);
    } else {
        // 6. Secondary Efficiency Reward:
        // Reward bins that are already well-utilized (low bin_residual).
        score -= (bin_capacity - bin_residual) as f64 * 0.08;
    }

    // 7. Large Item Specialization:
    // If the item is large, prevent it from taking space in bins that are already 
    // mostly full, as this might block future small items.
    if item_size > 50 && bin_residual < 40 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space penalty: If post_residual is in the range (0, 10), it is likely "unusable"
    // because the minimum item size is 10. Heavily penalize these "dead zones".
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead optimization: If the next item can fit in the current post_residual,
    // reward this bin to keep the packing tight.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open bin pressure: Penalize opening new bins unless the fit is perfect (0 residual).
    // If we are looking at a new bin (bin_residual == bin_capacity), increase cost
    // unless the item fits perfectly (which is impossible for items > 0) or we have too many open bins.
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Fitting constraints: If this is the only bin that can fit the item, 
    // it is a "mandatory" bin, so we lower the score to prioritize it over opening new ones.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Mean residual balancing: Penalize bins that deviate significantly from the mean,
    // encouraging more uniform utilization across all open bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Start with the post_residual as the primary Best Fit heuristic
    let mut score = post_residual as f64;

    // 1. Dynamic Dead-Space Penalty:
    // Penalize "sliver" residuals (1-18) which are too small for most items,
    // but reward near-perfect fits (0) more aggressively.
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual < 18 {
        score += 38.0 - (post_residual as f64 * 0.8);
    }

    // 2. Adaptive Lookahead:
    // If the next item fits, prioritize this bin. Scale by bin usage density.
    if next_item_size > 0 && post_residual >= next_item_size {
        let density_bonus = if open_bins_count > 10 { 15.0 } else { 5.0 };
        score -= (45.0 + density_bonus) + (next_item_size as f64 * 0.15);
    }

    // 3. Last-Resort Logic:
    // Force selection of the only valid bin, but minimize impact if it's already a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // 4. Mean-Variance Balancing:
    // Keep bins close to the mean to avoid creating "outlier" bins that are hard to fill.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.35;

    // 5. Progressive New Bin Threshold:
    // As the stream progresses, discourage opening new bins to force compaction.
    // If we are late in the stream, the cost of a new bin increases exponentially.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score += 55.0 + (progress * 45.0);
    } else {
        // 6. Secondary Tightness Reward:
        // Reward existing bins that are becoming full (low residual).
        score -= (bin_capacity - bin_residual) as f64 * 0.08;
    }

    // 7. Large Item Handling:
    // For items > 75, we prefer bins that are either nearly empty (to accommodate the bulk)
    // or perfectly sized to minimize fragmentation.
    if item_size > 75 {
        if bin_residual == bin_capacity {
            score -= 10.0;
        } else if post_residual == 0 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. If this is a new bin, apply a significant penalty to favor packing into existing bins.
    // The penalty is modulated by the number of open bins to prevent excessive fragmentation.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64 * 2.5);
    }

    // 2. Lookahead matching: Penalize the score if the post_residual is too small to fit the next item,
    // but only if a next item exists.
    if next_item_size > 0 {
        if post_residual < next_item_size {
