            score -= (post_residual - next_item_size) as f64 * 0.2;
        }
    }

    // 3. Efficiency alignment: Penalize if the bin becomes significantly less efficient than the global mean.
    // This helps maintain a uniform fill rate across all active bins.
    let efficiency_gap = (post_residual as f64 - mean_residual).abs();
    score += efficiency_gap * 0.1;

    // 4. Last chance heuristic: If this is the only bin that can fit the item, strongly prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Progression scaling: As we near the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Start with the base cost of the remaining space.
    let mut score = post_residual as f64;

    // 1. Dynamic "Dead Space" avoidance.
    // Instead of a static threshold, use the item_size to define the "danger zone".
    // If we leave a gap smaller than the current item, it's inefficient.
    if post_residual > 0 && post_residual < item_size {
        score += 45.0 + (item_size - post_residual) as f64;
    }

    // 2. Adaptive Lookahead. 
    // Reward bins that can accommodate BOTH the current and the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 42.0;
        // Further reward if this fit leaves a "clean" remainder (multiple of 10s are often safer in common distributions)
        if post_residual % 10 == 0 {
            score -= 8.0;
        }
    }

    // 3. Pressure-based Bin Allocation.
    // If fitting_bins_count is low, we are running out of options; prioritize packing tightly.
    if fitting_bins_count <= 2 {
        score -= (30.0 / fitting_bins_count as f64);
    }

    // 4. Global balance: Deviation from mean residual.
    // Use a more aggressive penalty for variance to encourage uniform bin filling.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.25;

    // 5. New bin thresholding (The "Empty Bin" gate).
    // Penalize opening a new bin exponentially as the stream progresses.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        // If we have many bins open, we should be extremely reluctant to open another.
        let capacity_penalty = (open_bins_count as f64 * 0.5) + (progress * 40.0);
        score += 45.0 + capacity_penalty;
    }

    // 6. Best Fit refinement.
    // Heavily penalize large residuals to force Best Fit behavior.
    score += (post_residual as f64) * 0.45;

    // 7. Small bin mitigation: If the bin is mostly full, prioritize finishing it.
    if post_residual < (bin_capacity / 8) {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Start with a base score derived from the post_residual.
    // Minimizing post_residual is the core of Best Fit.
    let mut score = post_residual as f64;

    // 1. Fragment Avoidance:
    // Penalize small, unusable residuals that are likely to become stranded dead-space.
    // Increased threshold to 30 to account for the typical distribution of items (1-100).
    if post_residual > 0 && post_residual < 30 {
        score += 48.0 - (post_residual as f64 * 0.5);
    }

    // 2. Lookahead Synergy:
    // Strongly prioritize bins that can accommodate the next item to minimize future fragmentation.
    // Added a bonus for 'sweet spot' residuals (post_residual ~ next_item_size + 20) to keep room for future growth.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0;
        if (post_residual - next_item_size) < 25 {
            score -= 20.0;
        }
    }

    // 3. Scarcity and Consolidation:
    // Strongly favor packing into existing bins if they are the only ones available.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // 4. Mean-Alignment Regularization:
    // Penalize outliers to keep bin usage density consistent across the stream.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.25;

    // 5. Dynamic New-Bin Thresholding:
    // Opening a new bin is a last resort. Penalty scales with the ratio of open bins
    // to total items to discourage premature allocation in long streams.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        let density_factor = (open_bins_count as f64 / (total_items as f64 / 50.0 + 1.0)).min(1.0);
        // Make opening bins more expensive early on, but allow it if current bins are full.
        score += 55.0 + (progress * 25.0) - (density_factor * 10.0);
    } else {
        // 6. Tight-Fit Reward:
        // Reward existing bins that result in high utilization.
        score += post_residual as f64 * 0.15;
    }

    // 7. Perfect Fit Bonus:
    // Direct reward for emptying a bin completely.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Penalize opening new bins heavily, but scale inversely with progress
    // to allow more flexibility towards the end of the stream.
    if is_new_bin {
        score += 45.0 * (1.0 - 0.5 * progress);
    }

    // 2. Best-Fit logic: Prefer bins where the item fits tightly.
    // We penalize larger post_residuals to keep bins full.
    score += (post_residual as f64) * 0.2;

    // 3. Lookahead: If the next item is large, favor bins that leave 
    // enough space for it (or avoid stranding the current bin if it's the only one).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Reward bins that can accommodate the next item
        } else if post_residual > 0 && post_residual < 20 {
            score += 25.0; // Penalize "dead space" that is too small for common items
        }
    }

    // 4. Global state: If we have many open bins, penalize opening another one.
    // If we have very few, be more lenient to avoid overcrowding.
    score += (open_bins_count as f64) * 2.5;

    // 5. Criticality adjustment: If this is the only bin that fits, 
    // reduce the penalty for a poor fit to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // 6. Mean residual balancing: Penalize bins that deviate significantly 
    // from the average residual to promote uniform bin filling.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Start with the primary goal: minimize post_residual (Best Fit principle)
    let mut score = post_residual as f64;

