    // 2. Lookahead Coupling
    // Dynamically reward bins that can accommodate the next item. 
    // We increase the weight as the stream progresses to tighten packing.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_weight = 38.0 + (step_index as f64 / total_items as f64) * 10.0;
        score -= lookahead_weight;
    }

    // 3. Pressure-based Bin Allocation
    // If we have many open bins, we should be more selective. 
    // If we have few, we should prioritize fitting the item into existing capacity.
    if open_bins_count > 10 {
        score += (open_bins_count as f64) * 0.05;
    }

    // 4. Residual Equilibrium
    // Penalize deviation from the global mean to keep bin usage density consistent.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.15;

    // 5. New-Bin Threshold (The "Oracle" Gate)
    // Opening a new bin is expensive. We only do it if the existing options are poor.
    if bin_residual == bin_capacity {
        // As the process nears completion, opening a new bin is increasingly costly.
        let completion_factor = (step_index as f64 / total_items as f64).powf(1.5);
        score += 42.0 + (completion_factor * 35.0);
    } else {
        // Reward bins that are already partially filled to maximize density.
        score -= (bin_capacity - bin_residual) as f64 * 0.08;
    }

    // 6. Tightness Bias
    // Penalize larger post_residuals more aggressively to favor "perfect fits".
    score += (post_residual as f64).powf(1.1) * 0.12;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

