    let mut score = post;

    // Penalty for creating "slivers" (very small residuals that are hard to fill).
    // Slivers in the [1, 9] range are particularly problematic.
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: If the next item fits into the post_residual, 
    // reward this bin to keep it "active" for the next item.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 40.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
    }

    // Dynamic thresholding: as the stream progresses, prioritize closing bins 
    // over opening new ones to improve packing density in the final phase.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin increases as we approach the end of the stream.
        score += 15.0 + (30.0 * progress);

        // If there are bins that can fit the item, discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // Coupling: Use mean_residual to dampen the score if the current bin is 
    // significantly worse than the average, preventing "outlier" bins.
    if (post as f64) > mean_residual {
        score += (post - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
