    let density_factor = (open_bins_count as f64) / (step_index as f64 * 0.5 + 1.0);
    score += density_factor * 5.0;

    // 4. Global Mean Balancing
    // Deviating from the mean is acceptable, but extreme outliers are heavily penalized
