    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.25;

    // 5. New Bin Thresholding (The "New Bin" Gate)
    // Opening a new bin is expensive. We scale this cost by the remaining stream 
