    // However, we apply a penalty if this bin is the only one that fits the current item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // 2. Lookahead mechanism: If the next item fits perfectly into the remaining space,
    // reward this bin placement significantly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual > next_item_size {
            // Reward bins that leave enough space for the next item to minimize fragmentation.
            score -= 10.0;
        } else {
            // Penalize creating "dead space" that is too small for the next item.
            score += 15.0;
        }
    }

    // 3. Global balance: If the post_residual is significantly lower than the mean_residual of other bins,
    // we are creating a "tight" bin, which is generally good.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 4. New Bin handling: If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // Only open a new bin if the current open bins are all "poor fits" (high post_residual).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // High threshold to avoid opening new bins unless necessary.
            score = 45.0;
        }
    }

    // 5. Progression adjustment: As the stream progresses, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
