    }

    // 4. Mean-Alignment Regularization: Penalize deviation from the mean to keep bin distribution uniform
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.42;

    // 5. Dynamic New-Bin Thresholding: Increased cost curve to force consolidation
    if bin_residual == bin_capacity {
